select p.patient_id, p.patient_name, i.project_name, p.create_time, p.enrollment_result, p.enrollment_result_content, p.research_id plan_research_id, p.enrollment_time,p.channel_type
from patient_info p, research_info i,patient_record pr
where i.id=p.research_id and pr.patient_id=p.patient_id
 and p.enrollment_handler_status = #{enrollmentHandlerStatus}
 and p.research_id = #{researchId}
 and p.patient_name like concat('%', #{patientName}, '%')
 and p.patient_id like concat('%', #{patientId}, '%')
 and p.allocated_status = #{allocatedStatus}

select p.research_id plan_research_id
from research_info i
INNER JOIN patient_info p on i.id=p.research_id

where  1=1
 and p.enrollment_handler_status = #{enrollmentHandlerStatus}
 and p.research_id = #{researchId}
 and p.patient_name like concat('%', #{patientName}, '%')
 and p.patient_id like concat('%', #{patientId}, '%')
 and p.allocated_status = #{allocatedStatus}
 and p.account_id = 0 
 and p.account_id != 0 
 and i.disease_type_id = #{diseaseTypeId}

select p.patient_id, p.patient_name, i.project_name, p.create_time, p.enrollment_result, p.enrollment_result_content ,isc.project_name scan_project_name
from patient_info p
inner join research_info i on i.id=p.research_id
left join research_info isc on p.plan_scan_research_id=isc.id
where p.allocated_status='1' and p.allocated_handler_status = #{allocatedHandlerStatus}
 and p.plan_research_id = #{researchId}
 and p.dept_id = #{deptId} and i.dept_id = #{deptId}
 and i.disease_type_id = #{diseaseTypeId}

