update patient_info
account_id = #{accountId}, person_id = #{personId}, patient_name = #{patientName}, clinic_no = #{clinicNo}, patient_code = #{patientCode}, adjust_type = #{adjustType}, old_patient_id = #{oldPatientId}, plan_research_id = #{planResearchId}, research_id = #{researchId}, dept_id = #{deptId}, doctor_id = #{doctorId}, patient_mobile = #{patientMobile}, patient_status = #{patientStatus}, enrollment_status = #{enrollmentStatus}, loss_cause = #{lossCause}, loss_cause_other = #{lossCauseOther}, update_by = #{updateBy}, create_by = #{createBy}, create_time = #{createTime}, update_time = #{updateTime}, enrollment_time = #{enrollmentTime}, enrollment_result = #{enrollmentResult}, enrollment_result_content = #{enrollmentResultContent}, enrollment_handler_status = #{enrollmentHandlerStatus}, allocated_status = #{allocatedStatus}, allocated_handler_status = #{allocatedHandlerStatus}, patient_activity_status = #{patientActivityStatus}, is_end_create_record = #{isEndCreateRecord}, channel_type = #{channelType}, is_show_app = #{isShowApp}, sms_send_count = #{smsSendCount}, province_id = #{provinceId}, city_id = #{cityId}, area_id = #{areaId}, visit_type = #{visitType}, generated_manually = #{generatedManually},
where patient_id = #{patientId}

