select f.patient_id, f.person_id, f.patient_name, p.card_id id_card, pc.mobile, f.create_time, f.plan_research_id, f.research_id, f.dept_id, f.account_id, p.phone_number base_mobile,f.enrollment_handler_status, f.enrollment_status, f.enrollment_result_content,case WHEN f.account_id = 0 THEN 0 else 1 END as bindStatus, f.patient_code from patient_info f INNER JOIN mp_person p on f.person_id=p.person_id LEFT JOIN mp_patient_account mpa on mpa.person_id=p.person_id LEFT JOIN patient_account pc on pc.account_id = mpa.account_id where 1=1
and f.person_id not in (select DISTINCT(person_id) from quit_record where is_agree = 1 and research_id = #{researchId})
and f.patient_id in
#{patientId}
and patient_id = #{patientId} and p.person_name like concat('%', #{patientName}, '%') and (f.research_id = #{researchId} or f.research_id is null) and f.account_id = 0 and f.account_id != 0 and f.enrollment_handler_status = #{enrollmentHandlerStatus} and f.enrollment_status = #{enrollmentStatus} and f.dept_id > 0 and date(f.enrollment_time) >=#{enrollmentTime}

SELECT a.patient_id patientId, a.person_id personId, a.patient_name patientName, a.research_id researchId, a.enrollment_time enrollmentTime, a.dept_id deptId, b.disease_type_id diseaseTypeId, a.generated_manually generatedManually FROM patient_info a INNER JOIN research_info b on a.research_id = b.id INNER join sys_user su on su.user_name=b.create_by WHERE a.enrollment_status = 1 and b.del_flag = '0' and b.research_status != 0 and a.patient_status != 6 and b.is_follow_rate =1
and DATE_FORMAT(a.enrollment_time,'%Y-%m-%d') >= #{inputStartTime}
and DATE_FORMAT(a.enrollment_time,'%Y-%m-%d') <= #{inputEndTime}
and a.dept_id = #{deptId}
and a.dept_id = #{roleDeptId}
and b.disease_type_id = #{diseaseId}
and a.research_id = #{researchId}
and (b.id in (select research_id from research_user_role where user_id = #{userId}) or su.user_id = #{userId} )
